// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address nft,
        address baseToken,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // Admissible domain: initialize must succeed and execute's guard must be meaningful.
        vm.assume(nft != address(0));
        vm.assume(nft.code.length == 0); // call to target succeeds if guard is bypassed
        vm.assume(feeRate <= 5_000);

        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // General rule: after initialize(_nft = nft), execute may NOT target the pool's nft.
        bool ok;
        try c.execute(nft, "") {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface INft {
    function balanceOf(address) external view returns (uint256);
}

contract InvMutTest is Test {
    C c;
    MockNft nft;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        uint256 tokenId,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint16 feeRate
    ) public {
        // keep the domain wide; only exclude values that make the admissible setup revert
        tokenId = bound(tokenId, 1, type(uint128).max);
        feeRate = bound(feeRate, 0, 5_000); // fee rate cap enforced by initialize
        nft = new MockNft();

        // drive c through initialize with a fuzzed virtual reserve pair and the deployed NFT counterparty
        c.initialize(
            address(0),
            address(nft),
            virtualBaseTokenReserves,
            virtualNftReserves,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );

        // fund the pool's NFT via the public deposit path (base token is ETH, so msg.value == baseTokenAmount == 0)
        nft.mint(tokenId, address(this));
        uint256[] memory ids = new uint256[](1);
        ids[0] = tokenId;
        c.deposit{value: 0}(ids, 0);

        // general rule: whatever address c reports as its nft holds the deposited token's balance in c.
        // Reference: c.nft() == address(nft) and balanceOf(c) == 1 => ok.
        // Mutant: c.nft() == address(0), the balance read through it fails => ok == false.
        bool ok;
        try INft(c.nft()).balanceOf(address(c)) returns (uint256 bal) {
            ok = (bal == 1);
        } catch {
            ok = false;
        }
        assertTrue(ok, "nft must be stored at initialize so deposits land in the pool");
    }
}

contract MockNft {
    mapping(uint256 => address) public ownerOf;
    mapping(address => uint256) public balanceOf;

    function mint(uint256 id, address to) external {
        ownerOf[id] = to;
        balanceOf[to]++;
    }

    function safeTransferFrom(address from, address to, uint256 id) external {
        delete ownerOf[id];
        balanceOf[from]--;
        balanceOf[to]++;
    }

    function safeTransferFrom(address from, address to, uint256 id, bytes calldata) external {
        safeTransferFrom(from, to, id);
    }
}
